begin;
create temp table _truoc as select count(*) n from public.question_bank;
insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '10', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl10-c3-20261020'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi có hai vec tơ lực $\\overrightarrow{F_{1}}$ và $\\overrightarrow{F_{2}}$ đồng quy, tạo thành hai cạnh của một hình bình hành thì vectơ tổng hợp lực $ F$ có thể</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai lực $\\overrightarrow{F_{1}}$ và $\\overrightarrow{F_{2}}$ đồng quy tại một điểm và tạo thành hai cạnh kề của một hình bình hành.</p><p class=\"text-base leading-relaxed my-2\">Theo quy tắc hình bình hành, hợp lực $\\overrightarrow{F}=\\overrightarrow{F_{1}}+\\overrightarrow{F_{2}}$ được biểu diễn bằng đường chéo của hình bình hành xuất phát từ điểm đồng quy.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A sai: hợp lực đặt tại điểm đồng quy, không phải tại một đỉnh bất kỳ của hình bình hành.</p><p class=\"text-base leading-relaxed my-2\">B đúng: hợp lực có phương là đường chéo của hình bình hành đi qua điểm đồng quy.</p><p class=\"text-base leading-relaxed my-2\">C sai: độ lớn $F=F_{1}+F_{2}$ chỉ đúng khi hai lực cùng phương, cùng chiều; ở đây hai lực tạo thành hai cạnh hình bình hành nên $F<F_{1}+F_{2}$ nói chung.</p><p class=\"text-base leading-relaxed my-2\">D sai: hợp lực nằm theo đường chéo, không trùng chiều với $\\overrightarrow{F_{1}}$ hay $\\overrightarrow{F_{2}}$ (trừ trường hợp suy biến).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là B.</p>","options":["có điểm đặt tại 1 đỉnh bất kỳ của hình bình hành.","có phương trùng với đường chéo của hình bình hành.","có độ lớn $F=F_{1}+F_{2}$.","cùng chiều với $\\overrightarrow{F_{1}}$ hoặc $\\overrightarrow{F_{2}}$."],"answer":1}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn ý <strong>sai</strong>. Lực được biểu diễn bằng một vectơ có</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực là đại lượng vectơ, được biểu diễn bằng một mũi tên có ba yếu tố: gốc, phương-chiều và độ dài.</p><p class=\"text-base leading-relaxed my-2\">A. Đúng: gốc của vectơ đặt tại điểm đặt của lực.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng: chiều của vectơ là chiều của lực.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng: độ dài vectơ tỉ lệ với độ lớn của lực theo một tỉ xích đã chọn.</p><p class=\"text-base leading-relaxed my-2\">D. Sai: phương của lực là phương của vectơ lực, không có quy định nào bắt buộc nó vuông góc với quỹ đạo chuyển động. Ví dụ, lực kéo của vật trên mặt phẳng nghiêng hay lực hướng tâm thường không vuông góc với quỹ đạo.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: ý sai là D.</p>","options":["gốc của vectơ là điểm đặt của lực.","chiều của vectơ là chiều của lực.","độ dài của vectơ biểu thị độ lớn của lực.","phương luôn vuông góc với quỹ đạo chuyển động."],"answer":3}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 3 Newton và lực tương tác","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Lực đặc trưng cho điều gì sau đây?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực là đại lượng vectơ đặc trưng cho tác dụng của vật này lên vật khác, là nguyên nhân làm thay đổi trạng thái chuyển động hoặc gây biến dạng của vật.</p><p class=\"text-base leading-relaxed my-2\">Xét các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Năng lượng là đại lượng đặc trưng cho khả năng sinh công, không phải lực.</p><p class=\"text-base leading-relaxed my-2\">B. Khối lượng đặc trưng cho mức quán tính của vật, không phải lực.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng: lực đặc trưng cho sự tương tác giữa các vật.</p><p class=\"text-base leading-relaxed my-2\">D. Vận tốc đặc trưng cho mức độ nhanh chậm của chuyển động, không phải lực.</p>","options":["Năng lượng của vật nhiều hay ít.","Vật có khối lượng lớn hay bé.","Tương tác giữa vật này lên vật khác.","Vật chuyển động nhanh hay chậm."],"answer":2}$q$::jsonb, 124, $q$Định luật 3 Newton và lực tương tác$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn phát biểu <strong>sai</strong> về tổng hợp và phân tích lực.</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\"><strong>A. Đúng.</strong> Hợp lực là một lực thay thế cho các lực đồng thời tác dụng lên vật và gây ra cùng hiệu quả.</p><p class=\"text-base leading-relaxed my-2\"><strong>B. Đúng.</strong> Để tổng hợp nhiều lực đồng thời, ta dùng quy tắc đa giác lực, hoặc áp dụng liên tiếp quy tắc hình bình hành cho từng cặp lực.</p><p class=\"text-base leading-relaxed my-2\"><strong>C. Đúng.</strong> Tổng hợp lực là thay nhiều lực bằng một hợp lực. Phân tích lực là thay một lực bằng các lực thành phần. Hai phép toán này ngược nhau.</p><p class=\"text-base leading-relaxed my-2\"><strong>D. Sai.</strong> Một lực có thể phân tích thành vô số cặp lực thành phần, không nhất thiết vuông góc với nhau. Việc chọn cặp vuông góc chỉ là một cách chọn thuận tiện, không phải là cách duy nhất.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phát biểu sai là <strong>D</strong>.</p>","options":["Hợp lực thay thế cho nhiều lực đồng thời tác dụng vào vật và cho cùng hiệu quả.","Tổng hợp một hệ lực tác dụng đồng thời vào vật ta dùng quy tắc đa giác lực hay dùng nối tiếp quy tắc hình bình hành.","Phép tổng hợp lực là ngược lại với phép phân tích lực.","Một lực tác dụng chỉ có thể phân tích thành một cặp lực thành phần duy nhất vuông góc với nhau."],"answer":3}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Phân tích lực theo hai phương vuông góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn phát biểu <strong>sai</strong>:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng. Trong hệ SI, đơn vị của lực là niutơn, kí hiệu $N$.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Phân tích lực là thay một lực bằng hai hoặc nhiều lực thành phần có tác dụng giống hệt lực ban đầu.</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Chỉ phân tích được một lực thành hai thành phần theo hai phương xác định khi hai phương đó không trùng hoặc không song song với nhau (và lực nằm trong mặt phẳng chứa hai phương). Không phải mọi cặp phương đều cho phép phân tích, nên không thể nói \"luôn luôn\" theo hai phương bất kì.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Tổng hợp lực là thay nhiều lực bằng một hợp lực; phân tích lực là phép ngược lại, thay một lực bằng nhiều lực thành phần.</p><p class=\"text-base leading-relaxed my-2\">Vậy phát biểu sai là phương án C.</p>","options":["Đơn vị của lực là Newton (N).","Phân tích lực là thay thế một lực bằng hai hay nhiều lực có tác dụng giống hệt như lực đó.","Luôn có thể phân tích lực theo hai phương bất kì.","Phân tích lực là phép làm ngược lại với tổng hợp lực."],"answer":2}$q$::jsonb, 120, $q$Phân tích lực theo hai phương vuông góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho hai lực $F_{1}$ và $ F_{2}$ đồng quy. Điều kiện nào sau đây để độ lớn hợp lực của hai lực bằng tổng của $ F_{1}+F_{2}$?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ lớn hợp lực của hai lực đồng quy $\\vec{F_1}$ và $\\vec{F_2}$ được xác định theo quy tắc hình bình hành:</p><p class=\"text-base leading-relaxed my-2\">$F^2 = F_1^2 + F_2^2 + 2F_1F_2\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">với $\\alpha$ là góc giữa hai lực $\\vec{F_1}$ và $\\vec{F_2}$.</p><p class=\"text-base leading-relaxed my-2\">Hợp lực có độ lớn bằng tổng $F_1+F_2$ khi và chỉ khi $F = F_1+F_2$, tức là:</p><p class=\"text-base leading-relaxed my-2\">$F_1^2 + F_2^2 + 2F_1F_2\\cos\\alpha = F_1^2 + F_2^2 + 2F_1F_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\cos\\alpha = 1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 0^\\circ$</p><p class=\"text-base leading-relaxed my-2\">Vậy hai lực phải song song cùng chiều (góc giữa chúng bằng $0^\\circ$).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>D</b>.</p>","options":["Hai lực song song ngược chiều.","Hai lực vuông góc nhau.","Hai lực hợp với nhau góc 60$^{0}$.","Hai lực song song cùng chiều."],"answer":3}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 3 Newton và lực tương tác","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai lực trực đối là hai lực</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai lực trực đối (hai lực đối nhau) là hai lực có cùng độ lớn, cùng phương (cùng giá), ngược chiều.</p><p class=\"text-base leading-relaxed my-2\">Phương án A sai: hai lực trực đối thường tác dụng vào hai vật khác nhau, ví dụ lực của tay tác dụng lên vật và lực phản lực của vật tác dụng lên tay.</p><p class=\"text-base leading-relaxed my-2\">Phương án B sai: hai lực này bằng nhau về độ lớn, không phải không bằng nhau.</p><p class=\"text-base leading-relaxed my-2\">Phương án C sai: hai lực này bằng nhau về độ lớn và bắt buộc phải cùng phương (cùng giá), không chỉ là \"không nhất thiết\".</p><p class=\"text-base leading-relaxed my-2\">Phương án D đúng: hai lực có cùng độ lớn, cùng phương, ngược chiều và tác dụng vào hai vật khác nhau.</p>","options":["tác dụng vào cùng một vật.","không bằng nhau về độ lớn.","bằng nhau về độ lớn nhưng không nhất thiết phải cùng giá.","có cùng độ lớn, cùng phương, ngược chiều tác dụng vào hai vật khác nhau."],"answer":3}$q$::jsonb, 124, $q$Định luật 3 Newton và lực tương tác$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Có hai lực đồng quy $\\overrightarrow{F_{1}}$ và $\\overrightarrow{F_{2}}$. Gọi $\\alpha$ là góc hợp bởi $\\overrightarrow{F_{1}}$ và $\\overrightarrow{F_{2}}$ và $\\overrightarrow{F}=\\overrightarrow{F_{1}}+\\overrightarrow{F_{2}}$. Nếu $ F=F_{1}+F_{2}$ thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Với hai lực đồng quy $\\overrightarrow{F_1}$ và $\\overrightarrow{F_2}$ có góc $\\alpha$ hợp bởi hai vectơ, độ lớn của hợp lực là: $F=\\sqrt{F_1^2+F_2^2+2F_1F_2\\cos\\alpha}$.</p><p class=\"text-base leading-relaxed my-2\">Theo đề, $F=F_1+F_2$. Bình phương hai vế: $F^2=(F_1+F_2)^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_1^2+F_2^2+2F_1F_2\\cos\\alpha=F_1^2+F_2^2+2F_1F_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 2F_1F_2\\cos\\alpha=2F_1F_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\cos\\alpha=1$ (vì $F_1,F_2>0$).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha=0^0$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hai lực cùng phương, cùng chiều thì hợp lực có độ lớn bằng tổng độ lớn. Chọn đáp án A.</p>","options":["α = 0$^{0}$.","α = 90$^{0}$.","α = 180$^{0}$.","0\\< α \\< 90$^{0.}$"],"answer":0}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho hai lực đồng qui có cùng độ lớn 600N. Hỏi góc giữa 2 lực bằng bao nhiêu thì hợp lực cũng có độ lớn bằng 600N ?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai lực đồng quy có cùng độ lớn $F_1 = F_2 = F = 600\\,\\text{N}$, hợp với nhau góc $\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Độ lớn hợp lực (quy tắc hình bình hành): $F_{hl}^2 = F_1^2 + F_2^2 + 2F_1F_2\\cos\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Với $F_1 = F_2 = F$: $F_{hl}^2 = 2F^2(1 + \\cos\\alpha) = 4F^2\\cos^2\\dfrac{\\alpha}{2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F_{hl} = 2F\\left|\\cos\\dfrac{\\alpha}{2}\\right|$.</p><p class=\"text-base leading-relaxed my-2\">Yêu cầu $F_{hl} = F = 600\\,\\text{N}$: $2F\\cos\\dfrac{\\alpha}{2} = F$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\cos\\dfrac{\\alpha}{2} = \\dfrac{1}{2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{\\alpha}{2} = 60^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 120^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: $\\alpha = 0^\\circ$ cho $F_{hl} = 1200\\,\\text{N}$; $\\alpha = 90^\\circ$ cho $F_{hl} \\approx 849\\,\\text{N}$; $\\alpha = 180^\\circ$ cho $F_{hl} = 0$. Không phương án nào khác thỏa mãn.</p><p class=\"text-base leading-relaxed my-2\">Vậy góc giữa hai lực là $120^\\circ$, đáp án D.</p>","options":["α = 0$^{0}$.","α = 90$^{0}$.","α = 180$^{0}$.","120$^{o}$."],"answer":3}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Moment lực và quy tắc moment","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai người công nhân khiêng một thùng hàng nặng 100kg bằng một đòn dài 2m, người thứ nhất đặt điểm treo của vật cách vai mình l,2m. Bỏ qua trọng lượng của đòn gánh và lấy g = 10m/s$^{2}$ , mỗi người chịu một lực là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trọng lượng của thùng hàng: $P = mg = 100 \\cdot 10 = 1000\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Khoảng cách từ điểm treo đến vai người thứ nhất: $d_1 = 1{,}2\\ \\text{m}$. Vì đòn dài $2\\ \\text{m}$ nên khoảng cách từ điểm treo đến vai người thứ hai: $d_2 = 2 - 1{,}2 = 0{,}8\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng của đòn (bỏ qua trọng lượng đòn, hai lực song song cùng chiều): $P_1 + P_2 = P = 1000\\ \\text{N}$ và momen lực đối với điểm treo bằng nhau: $P_1 \\cdot d_1 = P_2 \\cdot d_2$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $P_1 = \\dfrac{P \\cdot d_2}{d_1 + d_2} = \\dfrac{1000 \\cdot 0{,}8}{2} = 400\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $P_2 = P - P_1 = 1000 - 400 = 600\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $P_1 = 400\\ \\text{N}$ và $P_2 = 600\\ \\text{N}$, đáp án A.</p>","options":["$P_{1}$ = 400N; $P_{2}$ = 600N.","$P_{1}$ = 500N; $P_{2}$ = 400N.","$P_{1}$ = 200N; $P_{2}$ = 300N.","$P_{1}$ = 500N; $P_{2}$ = 300N."],"answer":0}$q$::jsonb, 130, $q$Moment lực và quy tắc moment$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho hai lực đồng quy có độ lớn $F_{1}=3N$ và $ F_{2}=4N$. Nếu hợp lực có độ lớn $ F=5N$ thì góc giữa hai lực $ F_{1}$ và $ F_{2}$ bằng bao nhiêu độ ?</p><p class=\"text-base leading-relaxed my-2\">| <strong>Đáp án:</strong> | <strong>9</strong> | <strong>0</strong> |     |     | |-------------|-------|-------|-----|-----|</p><p class=\"text-base leading-relaxed my-2\">: n130 fb + zalo Thu Minhn130 fb + zalo Thu Minh</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Gọi $\\alpha$ là góc giữa hai lực $\\vec{F_1}$ và $\\vec{F_2}$. Hợp lực của hai lực đồng quy có độ lớn được xác định theo định lí hàm cosin:</p><p class=\"text-base leading-relaxed my-2\">$F^2 = F_1^2 + F_2^2 + 2F_1F_2\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F_1 = 3\\ N$, $F_2 = 4\\ N$, $F = 5\\ N$:</p><p class=\"text-base leading-relaxed my-2\">$5^2 = 3^2 + 4^2 + 2\\cdot 3\\cdot 4\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 25 = 9 + 16 + 24\\cos\\alpha$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 24\\cos\\alpha = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\cos\\alpha = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 90^\\circ$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: góc giữa hai lực $F_1$ và $F_2$ là $90^\\circ$ (hai lực vuông góc nhau).</p>","answer":"90"}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho 3 lực có giá đồng quy, đồng phẳng $F_{1}, F_{2}, F_{3}$ lần lượt hợp với trục Ox những góc 0$^{0}$, 60$^{0}$, 120$^{0}$; $F_{1}$ = $F_{3}$ = $2F_{2}$ = 30N. Hợp lực của ba lực trên có độ lớn là bao nhiêu N?</p><p class=\"text-base leading-relaxed my-2\">| <strong>Đáp án:</strong> | <strong>4</strong> | <strong>5</strong> |     |     | |-------------|-------|-------|-----|-----|</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn hệ trục Oxy với trục Ox trùng phương của $\\vec{F_1}$. Hợp lực $\\vec{F}=\\vec{F_1}+\\vec{F_2}+\\vec{F_3}$ có độ lớn được xác định từ hình chiếu lên hai trục: $F_x=\\sum F_{ix}$, $F_y=\\sum F_{iy}$, $F=\\sqrt{F_x^2+F_y^2}$.</p><p class=\"text-base leading-relaxed my-2\">Theo đề: $F_1=F_3=30\\ \\text{N}$, $F_2=\\dfrac{30}{2}=15\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Hình chiếu lên Ox: $F_x=F_1\\cos 0^\\circ+F_2\\cos 60^\\circ+F_3\\cos 120^\\circ=30+15\\cdot\\dfrac{1}{2}+30\\cdot\\left(-\\dfrac{1}{2}\\right)=22{,}5\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Hình chiếu lên Oy: $F_y=F_1\\sin 0^\\circ+F_2\\sin 60^\\circ+F_3\\sin 120^\\circ=15\\cdot\\dfrac{\\sqrt{3}}{2}+30\\cdot\\dfrac{\\sqrt{3}}{2}=\\dfrac{45\\sqrt{3}}{2}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F=\\sqrt{F_x^2+F_y^2}=\\sqrt{22{,}5^2+\\left(\\dfrac{45\\sqrt{3}}{2}\\right)^2}=\\sqrt{506{,}25+1518{,}75}=\\sqrt{2025}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F=45\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy hợp lực của ba lực có độ lớn $45\\ \\text{N}$.</p>","answer":"45"}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi có hai vectơ lực ${\\overrightarrow{F}}_{1},$ ${\\overrightarrow{F}}_{2}$ đồng quy, tạo thành hai cạnh của một hình bình hành thì vectơ tổng hợp lực $ F$ có thể</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quy tắc hình bình hành: hai lực $\\overrightarrow{F}_1$, $\\overrightarrow{F}_2$ đồng quy tại O, lực tổng hợp $\\overrightarrow{F}=\\overrightarrow{F}_1+\\overrightarrow{F}_2$ có điểm đặt tại O và là đường chéo xuất phát từ O của hình bình hành.</p><p class=\"text-base leading-relaxed my-2\">Độ lớn: $F^2=F_1^2+F_2^2+2F_1F_2\\cos\\alpha$ với $\\alpha$ là góc giữa hai lực.</p><p class=\"text-base leading-relaxed my-2\">A sai: điểm đặt phải tại đỉnh O là điểm đồng quy, không phải đỉnh bất kì.</p><p class=\"text-base leading-relaxed my-2\">B sai: tổng hợp lực nằm theo đường chéo; chỉ trùng phương cạnh khi hai lực cùng phương (khi đó không còn là hình bình hành thực sự).</p><p class=\"text-base leading-relaxed my-2\">C đúng: khi $\\alpha=0$ thì $\\cos\\alpha=1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$F=F_1+F_2$, nên độ lớn này có thể xảy ra.</p><p class=\"text-base leading-relaxed my-2\">D sai: trường hợp tổng quát tổng hợp lực nằm trong góc giữa hai lực, không cùng chiều với lực nào.</p><p class=\"text-base leading-relaxed my-2\">Chọn C.</p>","options":["có điểm đặt tại 1 đỉnh bất kì của hình bình hành.","có phương trùng với cạnh của hình bình hành.","có độ lớn $F=F_{1}+F_{2}.$","cùng chiều với ${\\overrightarrow{F}}_{1}$ hoặc ${\\overrightarrow{F}}_{2}.$"],"answer":2}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tổng hợp hai lực đồng quy","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây về phép tổng hợp lực là <strong>sai</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tổng hợp lực là thay thế nhiều lực đồng thời tác dụng lên một vật bằng một lực duy nhất có tác dụng giống hệt. Về toán học, lực tổng hợp là tổng véctơ của các lực thành phần: $\\vec{F}=\\vec{F_1}+\\vec{F_2}+\\dots$</p><p class=\"text-base leading-relaxed my-2\">Với hai lực thành phần $\\vec{F_1}$, $\\vec{F_2}$, độ lớn của hợp lực thỏa mãn bất đẳng thức tam giác:</p><p class=\"text-base leading-relaxed my-2\">$|F_1-F_2|\\lt F\\lt F_1+F_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Độ lớn của lực tổng hợp luôn nhỏ hơn hoặc bằng tổng độ lớn của hai lực thành phần, đẳng thức xảy ra khi hai lực cùng phương, cùng chiều. Vậy không thể có $F\\gt F_1+F_2$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng, tổng hợp lực là phép cộng véctơ.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng, quy tắc hình bình hành xác định lực tổng hợp.</p><p class=\"text-base leading-relaxed my-2\">C. Sai, vì $F\\le F_1+F_2$ như đã chứng minh ở trên.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng, đây là định nghĩa của tổng hợp lực.</p><p class=\"text-base leading-relaxed my-2\"><b>Đáp án: C</b></p>","options":["Xét về mặt toán học, tổng hợp lực là phép cộng các véctơ lực cùng tác dụng lên một vật.","Lực tổng hợp có thể được xác định bằng quy tắc hình bình hành.","Độ lớn của lực tổng hợp có thể lớn hơn tổng độ lớn của hai lực thành phần.","Tổng hợp lực là phép thay thế các lực tác dụng đồng thời vào cùng một vật bằng một lực có tác dụng giống hệt các lực ấy."],"answer":2}$q$::jsonb, 119, $q$Tổng hợp hai lực đồng quy$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Điều kiện cân bằng của chất điểm","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Muốn cho một vật đứng yên dưới tác dụng của nhiều lực thì hợp lực của các lực tác dụng lên nó phải</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: nếu một vật đứng yên hoặc chuyển động thẳng đều khi tổng hợp các lực tác dụng lên nó bằng không thì vật giữ nguyên trạng thái.</p><p class=\"text-base leading-relaxed my-2\">Vật đứng yên dưới tác dụng của nhiều lực, nghĩa là gia tốc $a = 0$.</p><p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Newton: $\\vec{F}_{hl} = m\\vec{a}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\vec{F}_{hl} = m \\cdot 0 = 0$.</p><p class=\"text-base leading-relaxed my-2\">Vậy hợp lực của các lực tác dụng lên vật phải bằng không.</p>","options":["không đổi.","thay đổi.","bằng không.","khác không."],"answer":2}$q$::jsonb, 121, $q$Điều kiện cân bằng của chất điểm$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Moment lực và quy tắc moment","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai lực song song cùng chiều có độ lớn lần lượt bằng $F_{1}$ = 12N và $F_{2}$ = 16N có giá cách nhau 14cm. Giá của hợp lực của chúng cách lực</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hợp lực của hai lực song song cùng chiều: cùng chiều với hai lực, $F=F_1+F_2=28$ N, giá nằm trong khoảng giữa hai lực và thỏa mãn quy tắc $F_1d_1=F_2d_2$, với $d_1+d_2=14$ cm.</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{d_1}{d_2}=\\dfrac{F_2}{F_1}=\\dfrac{16}{12}=\\dfrac{4}{3}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow d_1=\\dfrac{4}{7}\\cdot 14=8$ cm</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow d_2=14-8=6$ cm</p><p class=\"text-base leading-relaxed my-2\">Vậy giá của hợp lực cách $F_1$ 8 cm và cách $F_2$ 6 cm. Chọn B.</p>","options":["$F_{1}$ 6cm, cách lực $F_{2}$ 8cm.","$F_{1}$ 8cm, cách lực $F_{2}$ 6cm.","$F_{1}$ 42cm, cách lực $F_{2}$ 56cm.","$F_{1}$ 56cm, cách lực $F_{2}$ 42cm."],"answer":1}$q$::jsonb, 130, $q$Moment lực và quy tắc moment$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Lực căng dây — hệ vật nối dây, ròng rọc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật có khối lượng 1 kg được treo vào một sợi dây nhẹ. Lực căng dây khi vật đứng yên là bao nhiêu N?. Lấy $g=9,8 m/s^{2}$.(Kết quả lấy đến 2 chữ số có nghĩa).</p><p class=\"text-base leading-relaxed my-2\">| <strong>Đáp án:</strong> | <strong>9</strong> | <strong>,</strong> | <strong>8</strong> |     | |-------------|-------|-------|-------|-----|</p><p class=\"text-base leading-relaxed my-2\">: n130 fb + zalo Thu Minhn130 fb + zalo Thu Minh</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi vật đứng yên, vật chịu hai lực cân bằng: trọng lực $\\vec{P}$ hướng xuống và lực căng dây $\\vec{T}$ hướng lên. Theo định luật I Newton, hợp lực bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Chọn chiều dương hướng lên. Điều kiện cân bằng: $T - P = 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T = P = mg$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $T = 1 \\cdot 9{,}8 = 9{,}8\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết quả lấy đến 2 chữ số có nghĩa: $T \\approx 9{,}8\\ \\text{N}$.</p>","answer":"9,8"}$q$::jsonb, 126, $q$Lực căng dây — hệ vật nối dây, ròng rọc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hợp lực tác dụng vào một vật đang chuyển động thẳng đều bằng hợp lực tác dụng vào vật</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: một vật đứng yên hoặc chuyển động thẳng đều khi hợp lực tác dụng lên nó bằng không.</p><p class=\"text-base leading-relaxed my-2\">Với vật chuyển động thẳng đều: $\\vec{F}_{hl} = \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">Với vật đứng yên: $\\vec{F}_{hl} = \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">Xét các phương án còn lại: chuyển động tròn đều có gia tốc hướng tâm nên $\\vec{F}_{hl} \\neq \\vec{0}$; rơi tự do chỉ chịu trọng lực nên $\\vec{F}_{hl} = m\\vec{g} \\neq \\vec{0}$; chuyển động nhanh dần đều có gia tốc khác 0 nên $\\vec{F}_{hl} \\neq \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hợp lực tác dụng lên vật chuyển động thẳng đều bằng hợp lực tác dụng lên vật đứng yên (cùng bằng 0). Chọn D.</p>","options":["chuyển động tròn đều.","rơi tự do.","chuyển động chuyển động nhanh dần đều.","đứng yên."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: nếu hợp lực tác dụng lên vật bằng không ($\\vec{F}_{hl} = \\vec{0}$) thì vật đang đứng yên sẽ tiếp tục đứng yên, còn vật đang chuyển động sẽ tiếp tục chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\"><b>A. Sai.</b> Khi không có lực tác dụng (hoặc hợp lực bằng 0), vật có thể đứng yên hoặc chuyển động thẳng đều, không nhất thiết đứng yên.</p><p class=\"text-base leading-relaxed my-2\"><b>B. Sai.</b> Lực tăng dần làm vật thay đổi vận tốc nhanh hơn, nhưng vật chậm dần hay nhanh dần còn phụ thuộc vào chiều của lực so với chiều chuyển động, không phụ thuộc việc độ lớn lực tăng hay giảm.</p><p class=\"text-base leading-relaxed my-2\"><b>C. Đúng.</b> Nếu vật chịu nhiều lực có hợp lực bằng 0 (các lực cân bằng nhau) thì vật vẫn chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\"><b>D. Sai.</b> Vật có thể chuyển động ngược chiều với lực tác dụng, ví dụ khi lực hãm làm vật chuyển động chậm dần theo chiều ngược lại với hướng của lực.</p>","options":["Khi không có lực tác dụng thì các vật sẽ đứng yên.","Vật chịu tác dụng của một lực có độ lớn tăng dần thì chuyển động chậm dần.","Một vật có thể chịu tác dụng đồng thời của nhiều lực mà vẫn chuyển động thẳng đều.","Vật không thể chuyển động ngược chiều với lực tác dụng lên nó."],"answer":2}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho các phát biểu sau  Định luật I Niu− tơn còn được gọi là định luật quán tính.  Mọi vật đều có xu hướng bảo toàn vận tốc của mình.  Chuyển động thẳng đều được gọi là chuyển động theo quán tính.  Quán tính là tính chất của mọi vật có xu hướng bảo toàn vận tốc cả về hướng và độ lớn.  Số phát biểu <strong>đúng</strong> là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật I Niu-tơn (định luật quán tính): nếu không có lực nào tác dụng hoặc các lực tác dụng cân bằng nhau thì vật đứng yên hoặc chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phát biểu:</p><p class=\"text-base leading-relaxed my-2\">1) Định luật I Niu-tơn còn gọi là định luật quán tính: <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">2) Mọi vật đều có xu hướng bảo toàn vận tốc của mình: <b>Đúng</b>, đây là nội dung của tính quán tính.</p><p class=\"text-base leading-relaxed my-2\">3) Chuyển động thẳng đều được gọi là chuyển động theo quán tính: <b>Đúng</b>, vì khi không có lực tác dụng (hoặc lực cân bằng) vật chuyển động thẳng đều theo quán tính.</p><p class=\"text-base leading-relaxed my-2\">4) Quán tính là tính chất của mọi vật có xu hướng bảo toàn vận tốc cả về hướng và độ lớn: <b>Đúng</b>, đây là định nghĩa quán tính.</p><p class=\"text-base leading-relaxed my-2\">Vậy có 4 phát biểu đúng, chọn B.</p>","options":["1.","4.","3.","2."],"answer":1}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe khách tăng tốc độ đột ngột thì các hành khách ngồi trên xe sẽ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Cơ sở:</strong> Theo định luật I Newton (quán tính), mọi vật có xu hướng giữ nguyên trạng thái chuyển động của nó khi không có lực tác dụng lên vật làm thay đổi trạng thái đó.</p><p class=\"text-base leading-relaxed my-2\"><strong>Phân tích:</strong> Khi xe khách tăng tốc đột ngột, phần sàn xe và ghế ngồi chuyển động nhanh lên, còn phần thân người hành khách do quán tính muốn giữ nguyên vận tốc cũ (nhỏ hơn vận tốc mới của xe).</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết quả:</strong> Thân người bị ngả về phía sau, tức là phía ngược với chiều chuyển động của xe.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Đáp án đúng là <strong>B</strong>.</p>","options":["ngả người sang bên trái.","ngả người về phía sau.","đỗ người về phía trước.","ngả người sang bên phải."],"answer":1}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trường hợp nào sau đây vật chuyển động theo quán tính?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật I Newton (định luật quán tính): Nếu không có lực nào tác dụng lên vật, hoặc hợp lực tác dụng lên vật bằng không, thì vật đứng yên hoặc chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Chuyển động theo quán tính là chuyển động của vật khi hợp lực tác dụng lên vật bằng $0$ (không có lực tác dụng).</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Chuyển động tròn đều có hướng vận tốc thay đổi, tức có gia tốc hướng tâm, nên cần có lực tác dụng. Loại.</p><p class=\"text-base leading-relaxed my-2\">B. Chuyển động trên đường thẳng có thể là nhanh dần hoặc chậm dần đều, khi đó hợp lực khác $0$. Loại.</p><p class=\"text-base leading-relaxed my-2\">C. Vật rơi tự do chịu tác dụng của trọng lực $P = mg \\neq 0$, nên có gia tốc $g$. Loại.</p><p class=\"text-base leading-relaxed my-2\">D. Khi tất cả các lực tác dụng lên vật mất đi thì hợp lực bằng $0$, vật chuyển động theo quán tính (thẳng đều). Chọn.</p>","options":["Vật chuyển động tròn đều.","Vật chuyển động trên một đường thẳng.","Vật rơi tự do từ trên cao xuống không ma sát.","Vật chuyển động khi tất cả các lực tác dụng lên vật mất đi."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quán tính của một vật phụ thuộc vào</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quán tính là tính chất của vật giữ nguyên trạng thái chuyển động hoặc đứng yên, chống lại sự thay đổi vận tốc.</p><p class=\"text-base leading-relaxed my-2\">Đại lượng đặc trưng cho mức quán tính của vật là khối lượng: vật có khối lượng càng lớn thì quán tính càng lớn.</p><p class=\"text-base leading-relaxed my-2\">Lực tác dụng không phải là yếu tố làm thay đổi quán tính; thể tích và mật độ khối lượng cũng không quyết định quán tính.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: quán tính của vật phụ thuộc vào khối lượng vật. Đáp án đúng là D.</p>","options":["lực tác dụng lên vật.","thể tích của vật.","mật độ khối lượng vật.","khối lượng vật."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Cơ sở:</b> Định luật I Newton: Vật đứng yên hoặc chuyển động thẳng đều khi không chịu lực nào tác dụng hoặc các lực tác dụng cân bằng nhau. Lực là nguyên nhân làm thay đổi vận tốc (gây gia tốc).</p><p class=\"text-base leading-relaxed my-2\"><b>Xét từng phương án:</b></p><p class=\"text-base leading-relaxed my-2\">A. Sai. Khi không có lực tác dụng, vật đang chuyển động vẫn tiếp tục chuyển động thẳng đều theo quán tính.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Khi thôi tác dụng lực, vật không tự dừng lại mà tiếp tục chuyển động với vận tốc không đổi (nếu không có ma sát hay lực cản).</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Lực làm thay đổi vận tốc, không nhất thiết vật chuyển động theo hướng của lực. Ví dụ quả bóng ném ngang vẫn chuyển động theo phương ngang dưới tác dụng của trọng lực theo phương thẳng đứng.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Theo định luật I Newton, nếu không có lực (hoặc hợp lực bằng 0) thì vận tốc không đổi; vậy vận tốc chỉ thay đổi khi có lực tác dụng.</p><p class=\"text-base leading-relaxed my-2\"><b>Kết luận:</b> Phát biểu đúng là phương án D.</p>","options":["Nếu không có lực tác dụng vào vật thì vật không chuyển động được<strong>.</strong>","Nếu thôi tác dụng lực vào vật thì vật dừng lại.","Vật luôn chuyển động theo hướng tác dụng của lực<strong>.</strong>","Vận tốc của vật chỉ thay đổi khi có lực tác dụng vào vật."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật sẽ đứng yên hay chuyển động thẳng đều khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Định luật I Newton:</strong> Nếu không có lực nào tác dụng lên vật hoặc các lực tác dụng lên vật cân bằng nhau thì vật đang đứng yên sẽ tiếp tục đứng yên, vật đang chuyển động sẽ tiếp tục chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng của vật: $\\vec{F}_{hl} = \\vec{F}_1 + \\vec{F}_2 + \\dots = \\vec{0}$ suy ra $\\vec{a} = \\vec{0}$, tức vận tốc không đổi.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai: chỉ chịu một lực khác không thì hợp lực khác không, vật có gia tốc.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng: các lực cân bằng nhau thì hợp lực bằng 0, vật đứng yên hoặc chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">C. Sai: độ lớn lực không đổi chưa đủ, các lực có thể không cân bằng về phương chiều.</p><p class=\"text-base leading-relaxed my-2\">D. Sai: hai lực bằng nhau về độ lớn nhưng có thể không cùng phương ngược chiều, hợp lực vẫn khác không.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Đáp án đúng là B.</p>","options":["chỉ chịu tác dụng của một lực.","các lực tác dụng vào vật cân bằng nhau.","các lực tác dụng vào vật có độ lớn không đổi.","chịu tác dụng của hai lực bằng nhau về độ lớn."],"answer":1}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Điều kiện cân bằng của chất điểm","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật nằm yên trên mặt bàn là do</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật nằm yên trên mặt bàn theo định luật I Newton: vật đứng yên khi hợp lực tác dụng lên nó bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Các lực tác dụng lên vật gồm trọng lực $\\vec{P}$ (hướng xuống, do Trái Đất hút) và phản lực $\\vec{N}$ của mặt bàn (hướng lên).</p><p class=\"text-base leading-relaxed my-2\">Điều kiện cân bằng: $\\vec{P}+\\vec{N}=\\vec{0}$, tức $P=N$ và hai lực cùng phương, ngược chiều.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A sai: vật còn chịu phản lực của bàn.</p><p class=\"text-base leading-relaxed my-2\">B sai: vật có chịu lực, chỉ là hợp lực bằng 0.</p><p class=\"text-base leading-relaxed my-2\">C sai: lực không nhỏ; trọng lực của vật có độ lớn $P=mg$ đáng kể.</p><p class=\"text-base leading-relaxed my-2\">D đúng: lực hút của Trái Đất (trọng lực) cân bằng với phản lực của bàn.</p>","options":["vật chỉ chịu tác dụng của lực hút Trái Đất.","không có lực tác dụng lên vật.","các lực tác dụng lên vật có cường độ quá nhỏ.","lực hút của Trái Đất lên vật cân bằng với phản lực của bàn."],"answer":3}$q$::jsonb, 121, $q$Điều kiện cân bằng của chất điểm$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi đang đi xe đạp trên đường nằm ngang, nếu ta ngừng đạp, xe vẫn đi tiếp chứ chưa dừng ngay. Đó là nhờ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton (định luật quán tính): mọi vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều khi không có lực nào tác dụng lên nó hoặc các lực tác dụng cân bằng nhau.</p><p class=\"text-base leading-relaxed my-2\">Khi ngừng đạp, lực kéo của người không còn tác dụng lên xe theo phương chuyển động. Trọng lượng và phản lực của mặt đường cân bằng nhau theo phương thẳng đứng nên không làm thay đổi chuyển động theo phương ngang.</p><p class=\"text-base leading-relaxed my-2\">Xe vẫn tiếp tục chuyển động là do <strong>quán tính</strong> của xe, tức xu hướng bảo toàn vận tốc của vật. Lực ma sát chỉ làm xe chậm dần rồi dừng lại, không phải nguyên nhân khiến xe tiếp tục đi.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: <strong>C. quán tính của xe.</strong></p>","options":["trọng lượng của xe.","lực ma sát.","quán tính của xe.","phản lực của mặt đường."],"answer":2}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Kiến thức:</strong> Theo định luật II Newton, gia tốc của vật tỉ lệ thuận với hợp lực tác dụng lên vật: $\\vec{a}=\\dfrac{\\vec{F}_{hl}}{m}$. Vì gia tốc là đại lượng đặc trưng cho sự biến đổi vận tốc nên lực tác dụng làm vận tốc của vật thay đổi.</p><p class=\"text-base leading-relaxed my-2\"><strong>Phân tích từng phương án:</strong></p><p class=\"text-base leading-relaxed my-2\">A. Sai. Theo định luật I Newton, nếu không có lực tác dụng (hoặc hợp lực bằng 0) thì vật đứng yên hoặc chuyển động thẳng đều, không phải lúc nào cũng đứng yên.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Theo định luật I Newton, vật đang chuyển động mà không chịu lực nào thì sẽ tiếp tục chuyển động thẳng đều (quán tính), không dừng lại.</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Lực tác dụng chỉ quyết định sự thay đổi vận tốc; hướng chuyển động có thể khác hướng lực (ví dụ vật ném xiên, chuyển động tròn đều).</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Có lực tác dụng (hợp lực khác 0) thì vật có gia tốc $\\vec{a}\\neq \\vec{0}$, do đó vận tốc thay đổi về độ lớn hoặc hướng.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Phát biểu đúng là D.</p>","options":["Nếu không có lực tác dụng vào vật thì vật không chuyển động được.","Nếu thôi không tác dụng lực vào vật thì vật đang chuyển động sẽ dừng lại.","Vật nhất thiết phải chuyển động theo hướng của lực tác dụng.","Nếu có lực tác dụng lên vật thì vận tốc của vật bị thay đổi."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vật nào sau đây chuyển động theo quán tính?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động theo quán tính là chuyển động giữ nguyên vận tốc (cả về hướng lẫn độ lớn) của vật khi không chịu tác dụng của lực nào hoặc hợp lực tác dụng lên vật bằng không.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton, vật không chịu lực hoặc có hợp lực bằng 0 thì giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Chuyển động tròn đều: vận tốc đổi hướng liên tục, có gia tốc hướng tâm $a_{ht}=\\dfrac{v^2}{r}$ nên hợp lực khác 0. Loại.</p><p class=\"text-base leading-relaxed my-2\">B. Chuyển động trên quỹ đạo thẳng: chưa đủ điều kiện, vật có thể nhanh dần hoặc chậm dần đều (có lực tác dụng). Loại.</p><p class=\"text-base leading-relaxed my-2\">C. Chuyển động thẳng đều: vận tốc không đổi, gia tốc $a=0$, hợp lực bằng 0. Đây là chuyển động theo quán tính.</p><p class=\"text-base leading-relaxed my-2\">D. Rơi tự do: vật chịu trọng lực không cân bằng, gia tốc $g\\neq 0$. Loại.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: vật chuyển động thẳng đều chuyển động theo quán tính. Chọn đáp án C.</p>","options":["Vật chuyển động tròn đều.","Vật chuyển động trên quỹ đạo thẳng.","Vật chuyển động thẳng đều.","Vật chuyển động rơi tự do."],"answer":2}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe ô tô đang chuyển động thẳng với vận tốc không đổi là 20 m/s. Hợp lực tác dụng lên ô tô có độ lớn bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: một vật đang đứng yên hoặc chuyển động thẳng đều thì hợp lực tác dụng lên vật bằng không.</p><p class=\"text-base leading-relaxed my-2\">Ô tô chuyển động thẳng với vận tốc không đổi $v = 20\\ \\text{m/s}$, tức là chuyển động thẳng đều, gia tốc $a = 0$.</p><p class=\"text-base leading-relaxed my-2\">Áp dụng định luật II Newton: $\\vec{F}_{hl} = m\\vec{a} = m \\cdot 0 = 0$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hợp lực tác dụng lên ô tô có độ lớn $0\\ \\text{N}$, đáp án B.</p>","options":["20 N.","0N.","10 N.","- 20 N."],"answer":1}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật đang chuyển động với vận tốc 3 m/s. Nếu bỗng nhiên các lực tác dụng lên nó mất đi thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: nếu không có lực nào tác dụng lên vật (hoặc hợp lực bằng không) thì vật đang đứng yên sẽ tiếp tục đứng yên, còn vật đang chuyển động sẽ tiếp tục chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Áp dụng: vật đang chuyển động với $v = 3\\ \\text{m/s}$, khi các lực mất đi thì hợp lực bằng $0$, nên vật giữ nguyên vận tốc về độ lớn và hướng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: vật tiếp tục chuyển động thẳng đều theo hướng cũ với vận tốc $3\\ \\text{m/s}$. Đáp án B.</p>","options":["vật dừng lại ngay.","vật tiếp tục chuyển động theo hướng cũ với vận tốc 3 m/s.","vật đổi hướng chuyển động.","vật chuyển động chậm dần rồi dừng lại."],"answer":1}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về tác dụng của lực đối với chuyển động, điều nào dưới đây <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Phân tích từng phương án:</strong></p><p class=\"text-base leading-relaxed my-2\"><strong>A sai.</strong> Theo định luật I Newton, vật không chịu lực (hoặc hợp lực bằng 0) vẫn có thể chuyển động thẳng đều. Lực không phải điều kiện để vật chuyển động, mà là nguyên nhân làm thay đổi vận tốc.</p><p class=\"text-base leading-relaxed my-2\"><strong>B sai.</strong> Lực tăng dần chưa đủ để kết luận vật nhanh dần. Chiều của lực so với chiều chuyển động mới quyết định. Nếu lực ngược chiều vận tốc thì vật chậm dần, dù độ lớn lực tăng.</p><p class=\"text-base leading-relaxed my-2\"><strong>C đúng.</strong> Khi nhiều lực tác dụng đồng thời có hợp lực bằng 0 (cân bằng), theo định luật I Newton vật đứng yên hoặc chuyển động thẳng đều. Ví dụ: vật trượt đều trên mặt phẳng ngang khi lực kéo cân bằng lực ma sát và các lực khác.</p><p class=\"text-base leading-relaxed my-2\"><strong>D sai.</strong> Vật có thể chuyển động ngược chiều với lực tác dụng. Ví dụ: quả bóng ném lên cao chuyển động đi lên trong khi trọng lực hướng xuống, hoặc vật chậm dần khi lực cản ngược chiều chuyển động.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Đáp án đúng là <strong>C</strong>.</p>","options":["Nếu không có lực tác dụng vào vật thì vật không thể chuyển động.","Một vật bất kì chịu tác dụng của một lực có độ lớn tăng dần thì chuyển động nhanh dần.","Một vật có thể chịu tác dụng đồng thời của nhiều lực mà vẫn chuyển động thẳng đều.","Không vật nào có thể chuyển động ngược chiều với lực tác dụng lên nó."],"answer":2}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi đang đi ô tô trên đường nằm ngang, nếu ta phanh gấp, xe vẫn tự di chuyển. Đó là nhờ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton (định luật quán tính): một vật sẽ giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều khi không có lực nào tác dụng lên nó hoặc các lực tác dụng cân bằng nhau.</p><p class=\"text-base leading-relaxed my-2\">Khi phanh gấp, bánh xe bị hãm lại nên chuyển động chậm lại, nhưng thân xe và người trên xe vẫn có xu hướng giữ nguyên vận tốc cũ do <b>quán tính</b>, nên xe vẫn tiếp tục di chuyển một quãng đường nhất định trước khi dừng hẳn.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng và phản lực của mặt đường cân bằng nhau theo phương thẳng đứng, nên không làm xe chuyển động tiếp; lực ma sát lớn (không phải nhỏ) khi phanh gấp làm xe dừng lại nhanh hơn.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: <b>C</b>. quán tính của xe.</p>","options":["trọng lượng của xe.","lực ma sát nhỏ.","quán tính của xe.","phản lực của mặt đường."],"answer":2}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về tác dụng của lực lên vật, phát biểu nào dưới đây <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton (định luật quán tính): vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều khi không có lực nào tác dụng hoặc hợp lực bằng không.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: nếu vận tốc của vật thay đổi (về độ lớn hoặc hướng) thì hợp lực tác dụng lên vật phải khác không.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Đúng, vì thay đổi vận tốc là gia tốc $a\\neq 0$, nên theo định luật II Newton $\\vec{F}_{hl}=m\\vec{a}\\neq \\vec{0}$.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Lực làm thay đổi vận tốc, không buộc vật chuyển động theo hướng của lực. Ví dụ quả bóng ném ngang vẫn rơi theo phương thẳng đứng dưới tác dụng của trọng lực.</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Khi không còn lực tác dụng, vật đang chuyển động sẽ tiếp tục chuyển động thẳng đều (quán tính), không dừng lại ngay.</p><p class=\"text-base leading-relaxed my-2\">D. Sai. Nếu không có lực nào (hoặc hợp lực bằng không) tác dụng, vật chuyển động thẳng đều và có thể chuyển động mãi mãi.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là A.</p>","options":["Khi vật thay đổi vận tốc thì bắt buộc phải có lực tác dụng vào vật.","Vật bắt buộc phải chuyển động theo hướng của lực tác dụng vào nó.","Nếu không còn lực nào tác dụng vào vật đang chuyển động thì vật phải lập tức dừng lại.","Một vật không thể liên tục chuyển động mãi mãi nếu không có lực nào tác dụng vào nó."],"answer":0}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khối lượng là đại lượng đặc trưng cho</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng là đại lượng đặc trưng cho mức quán tính của vật: khối lượng càng lớn thì vật càng khó thay đổi vận tốc (quán tính càng lớn).</p><p class=\"text-base leading-relaxed my-2\">Phân tích các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Trọng lượng là lực hấp dẫn tác dụng lên vật, $P = mg$, phụ thuộc vào gia tốc trọng trường nên không phải đặc trưng của khối lượng.</p><p class=\"text-base leading-relaxed my-2\">B. Tác dụng làm quay của lực quanh một trục là momen lực, không phải khối lượng.</p><p class=\"text-base leading-relaxed my-2\">C. Thể tích là đại lượng hình học, không đặc trưng cho khối lượng (khối lượng bằng khối lượng riêng nhân thể tích).</p><p class=\"text-base leading-relaxed my-2\">D. Đúng.</p>","options":["trọng lượng của vật.","tác dụng làm quay của lực quanh một trục","thể tích của vật.","mức quán tính của vật."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi một xe bus tăng tốc đột ngột thì các hành khách</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hiện tượng này liên quan đến <b>quán tính</b> (định luật I Newton): mọi vật có xu hướng giữ nguyên trạng thái chuyển động của nó khi không có lực tác dụng lên vật.</p><p class=\"text-base leading-relaxed my-2\">Trước khi xe tăng tốc, hành khách chuyển động cùng xe với vận tốc $v$.</p><p class=\"text-base leading-relaxed my-2\">Khi xe bus tăng tốc đột ngột, phần thân xe và sàn xe được đẩy về phía trước. Phần thân người tiếp xúc với sàn nên cũng được tăng tốc theo, nhưng phần thân trên (đầu, vai) do quán tính có xu hướng giữ nguyên vận tốc cũ $v$ so với mặt đất.</p><p class=\"text-base leading-relaxed my-2\">Vì vậy, so với xe, phần trên cơ thể bị đẩy <b>về phía sau</b>, hành khách bị ngả người ra sau.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B. ngả người về phía sau</b>.</p>","options":["dừng lại ngay.","ngả người về phía sau.","chúi người về phía trước.","ngả người sang bên cạnh"],"answer":1}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: nếu không có lực nào tác dụng (hoặc hợp lực bằng 0) thì vật đứng yên hoặc chuyển động thẳng đều. Lực không phải nguyên nhân duy trì chuyển động.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai. Vật vẫn có thể chuyển động thẳng đều khi không có lực tác dụng (hoặc hợp lực bằng 0), vì vật giữ nguyên trạng thái chuyển động.</p><p class=\"text-base leading-relaxed my-2\">B. Sai. Chuyển động tròn đều có gia tốc hướng tâm $a_{ht}=\\dfrac{v^2}{r}\\neq 0$, theo định luật II Newton phải có hợp lực hướng tâm $F_{ht}=ma_{ht}\\neq 0$ tác dụng lên vật.</p><p class=\"text-base leading-relaxed my-2\">C. Sai. Lực không duy trì chuyển động; vật chuyển động đều không cần lực tác dụng.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Lực là nguyên nhân làm thay đổi trạng thái chuyển động (thay đổi vận tốc, tức có gia tốc) của vật, theo $\\vec{F}=m\\vec{a}$.</p>","options":["Nếu không có lực tác dụng vào vật thì vật không thể chuyển động được.","Không cần có lực tác dụng vào vật thì vật vẫn chuyển động tròn đều được.","Lực là nguyên nhân duy trì chuyển động của một vật.","Lực là nguyên nhân làm biến đổi chuyển động của vật."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điều gì sẽ có thể xảy ra với người lái xe máy chạy ngay sau một xe tải nếu xe tải dừng đột ngột?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Kiến thức:</strong> Định luật I Newton (quán tính): mọi vật có xu hướng giữ nguyên trạng thái chuyển động khi không có lực tác dụng làm thay đổi trạng thái đó.</p><p class=\"text-base leading-relaxed my-2\"><strong>Phân tích:</strong> Khi xe tải dừng đột ngột, xe máy phía sau cũng bắt đầu giảm tốc, nhưng người lái và xe đang chuyển động với vận tốc $v$ nên người lái có xu hướng tiếp tục chuyển động về phía trước theo quán tính.</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Nếu không kịp phanh, người lái có thể bị đẩy về phía trước và va vào xe tải. Phương án D đúng.</p><p class=\"text-base leading-relaxed my-2\">Các phương án còn lại sai: A (có nguy hiểm), B (người bị đẩy về phía trước chứ không phải phía sau), C (không có lực nào đẩy xe đổ sang phải).</p>","options":["Không có vấn đề gì.","Xe máy sẽ bị văng về phía sau.","Xe máy sẽ bị đổ sang phải.","Xe máy sẽ bị đâm vào xe tải."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi đang đi xe máy trên đường nằm ngang, nếu ta phanh xe, xe vẫn tự di chuyển. Đó là nhờ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton (định luật quán tính): mọi vật đều có xu hướng bảo toàn vận tốc cả về hướng và độ lớn khi không chịu lực nào tác dụng hoặc các lực tác dụng cân bằng.</p><p class=\"text-base leading-relaxed my-2\">Khi phanh, bánh xe bị hãm và chuyển động chậm lại, nhưng xe và người trên xe vẫn có xu hướng giữ nguyên vận tốc cũ nên xe vẫn tiếp tục di chuyển thêm một quãng đường trước khi dừng hẳn.</p><p class=\"text-base leading-relaxed my-2\">Đây là tính chất quán tính của xe, tức là khả năng của vật bảo toàn vận tốc.</p><p class=\"text-base leading-relaxed my-2\">Các phương án khác không đúng: trọng lượng và phản lực của mặt đường là hai lực cân bằng theo phương thẳng đứng, không làm xe chuyển động tiếp theo phương ngang; lực ma sát lớn khi phanh chứ không nhỏ, và chính ma sát mới làm xe dừng lại.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <strong>C</strong>.</p>","options":["trọng lượng của xe.","lực ma sát nhỏ.","quán tính của xe.","phản lực của mặt đường."],"answer":2}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Định luật 1 Newton và quán tính","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hợp lực tác dụng vào một vật đang chuyển động thẳng đều bằng hợp lực tác dụng vào vật</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật I Newton: nếu một vật không chịu tác dụng của lực nào, hoặc chịu tác dụng của các lực cân bằng (hợp lực bằng 0), thì vật đứng yên hoặc chuyển động thẳng đều.</p><p class=\"text-base leading-relaxed my-2\">Vật chuyển động thẳng đều có gia tốc $a = 0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Theo định luật II Newton: $\\vec{F}_{hl} = m\\vec{a} = m \\cdot 0 = 0$.</p><p class=\"text-base leading-relaxed my-2\">Vật đứng yên cũng có gia tốc bằng 0, nên hợp lực tác dụng lên nó cũng bằng 0.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Hợp lực tác dụng vào vật chuyển động thẳng đều bằng hợp lực tác dụng vào vật đứng yên (đều bằng 0).</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng: D.</p>","options":["chuyển động tròn đều.","tự do.","chuyển động nhanh dần đều.","đứng yên."],"answer":3}$q$::jsonb, 122, $q$Định luật 1 Newton và quán tính$q$)) as v(q, tid, tname)
